package warranty

import (
	"errors"
	"testing"
	"time"
)

// 本文件回归保障“保修请求先提交、产品资料后登记”：SubmitRequest 允许
// 关联尚未登记的产品，产品缺失留待资格查询与预留时报告（ErrNotFound）；
// 失败不产生承诺、不占用库存，并在该请求的预留历史中留下资格依据与库存
// 依据均为空的产品缺失记录。随后补登产品资料即作用于原请求——无需再次
// 提交或替换请求——资格按补登条款正常判断，沿用此前失败的承诺编号与
// 预留内容重试即可成功；早先的缺失记录不被补登资料回填、不被成功记录
// 覆盖，两条记录各有自己的递增序号。若补登条款把原请求的故障代码列为
// 除外，资格明确显示除外原因、预留返回 ErrIneligible，本次失败历史保存
// 已取得的资格与库存依据，而原请求的产品编号、故障代码及此前缺失记录
// 仍然保留。测试只沿用既有公开入口与现有错误类别，不改变任何规则。

// 本文件专用编号，避免与其他测试文件混用。
const (
	lpProductID   = "p-late"
	lpOtherProdID = "p-late-other"
	lpPartID      = "part-late"
	lpReqID       = "r-late"
	lpOtherReqID  = "r-late-other"
	lpCommitID    = "c-late"
	lpOtherCommit = "c-late-other"
	lpFaultCode   = "NOISE"
)

// lpClock 汇集主例的全部时刻。
type lpClock struct {
	purchase  time.Time // 补登产品的购买时刻
	deadline  time.Time // 保修截止时刻：购买时刻起第三十天
	firstAt   time.Time // 产品缺失期间资格查询与首次预留的当次当前时刻
	firstExp  time.Time // 首次预留的到期时刻，晚于 firstAt
	secondAt  time.Time // 补登后再次判断与重试预留的当次当前时刻
	secondExp time.Time // 重试预留的到期时刻，晚于 secondAt
}

// lpBaseScenario 构造用户给出的主例：备件 part-late 有 10 件实物；另一张
// 关联已登记产品的合格请求 r-late-other 已有效占用 4 件。新请求 r-late
// 关联尚未登记的产品 p-late，故障代码 NOISE 非空。此刻 p-late 尚未登记。
func lpBaseScenario(t *testing.T) (*Store, lpClock) {
	t.Helper()
	clk := lpClock{
		purchase:  t0,
		deadline:  t0.Add(30 * day),
		firstAt:   t0.Add(10 * day),
		firstExp:  t0.Add(45 * day),
		secondAt:  t0.Add(11 * day),
		secondExp: t0.Add(46 * day),
	}

	s := NewStore()
	// 另一张合格请求依赖的已登记产品（条款不除外 NOISE）。
	if err := s.RegisterProduct(lpOtherProdID, t0, 365, nil); err != nil {
		t.Fatalf("register other product: %v", err)
	}
	if err := s.RegisterPart(lpPartID, 10); err != nil {
		t.Fatalf("register part: %v", err)
	}
	// 另一张合格请求，并有效占用 4 件。
	if err := s.SubmitRequest(lpOtherReqID, lpOtherProdID, "OTHER_FAULT"); err != nil {
		t.Fatalf("submit other request: %v", err)
	}
	if _, err := s.Reserve(lpOtherCommit, lpOtherReqID, lpPartID, 4, clk.firstExp, clk.firstAt); err != nil {
		t.Fatalf("reserve other commitment: %v", err)
	}
	// 新请求关联一个尚未登记的产品，故障代码非空：提交本身必须成功。
	if err := s.SubmitRequest(lpReqID, lpProductID, lpFaultCode); err != nil {
		t.Fatalf("submit request before product registration: %v", err)
	}
	return s, clk
}

// assertStock10x6 断言备件账目保持：实物 10 件、有效占用 4 件、可承诺 6 件。
func assertStock10x6(t *testing.T, s *Store, now time.Time) {
	t.Helper()
	st, err := s.PartStatus(lpPartID, now)
	if err != nil {
		t.Fatalf("part status: %v", err)
	}
	if st.PhysicalRemaining != 10 || st.ActiveOccupied != 4 || st.Committable != 6 {
		t.Fatalf("stock = phys %d / occupied %d / committable %d, want 10/4/6",
			st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
	}
}

// assertMissingProductFailureRecord 断言产品缺失失败记录的完整内容：保存
// 提交编号、备件、数量、到期时刻与当次当前时刻；即使备件已经存在，资格
// 依据和库存依据也都为空。
func assertMissingProductFailureRecord(t *testing.T, rec HistoryRecord, seq int, clk lpClock) {
	t.Helper()
	if rec.Seq != seq {
		t.Fatalf("seq = %d, want %d", rec.Seq, seq)
	}
	if rec.Success {
		t.Fatalf("missing-product record marked success: %+v", rec)
	}
	if rec.Error != HistoryErrorProductNotFound {
		t.Fatalf("error category = %q, want %q", rec.Error, HistoryErrorProductNotFound)
	}
	if rec.CommitID != lpCommitID || rec.PartID != lpPartID || rec.Quantity != 3 {
		t.Fatalf("submission content = %q/%q/%d, want %q/%q/3",
			rec.CommitID, rec.PartID, rec.Quantity, lpCommitID, lpPartID)
	}
	if !rec.Expiry.Equal(clk.firstExp) || !rec.Now.Equal(clk.firstAt) {
		t.Fatalf("times = expiry %v now %v, want %v / %v",
			rec.Expiry, rec.Now, clk.firstExp, clk.firstAt)
	}
	// 即使备件已经存在，这条记录的资格依据和库存依据也都为空。
	if rec.Eligibility != nil {
		t.Fatalf("missing-product record must have nil eligibility, got %+v", rec.Eligibility)
	}
	if rec.StockBasis != nil {
		t.Fatalf("missing-product record must have nil stock basis even though part exists, got %+v", rec.StockBasis)
	}
}

// TestRequestBeforeProduct_MissingPeriod 产品缺失期间：资格查询（Evaluate
// 与 RequestView）和预留都返回 ErrNotFound；失败不产生承诺，实物仍 10 件、
// 有效占用 4 件、可承诺 6 件；预留历史留下产品缺失的失败记录，保存提交
// 编号、备件、数量、到期时刻和当次当前时刻，且资格依据、库存依据均为空。
func TestRequestBeforeProduct_MissingPeriod(t *testing.T) {
	s, clk := lpBaseScenario(t)

	// 提交时不校验产品：请求确实已保存，且保留原产品编号与故障代码。
	req, err := s.Request(lpReqID)
	if err != nil {
		t.Fatalf("request lookup: %v", err)
	}
	if req.ProductID != lpProductID || req.FaultCode != lpFaultCode {
		t.Fatalf("saved request = %+v, want product %q fault %q", req, lpProductID, lpFaultCode)
	}
	// 产品确实尚未登记。
	if _, err := s.Product(lpProductID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("product should be missing: got %v", err)
	}

	// 资格查询：产品缺失返回 ErrNotFound。
	if _, err := s.Evaluate(lpReqID, clk.firstAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("evaluate while product missing: got %v, want ErrNotFound", err)
	}
	// 按请求查看同样沿用现有错误类别报告缺失。
	if _, err := s.RequestView(lpReqID, clk.firstAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("request view while product missing: got %v, want ErrNotFound", err)
	}

	// 预留 3 件，到期时刻晚于当次时刻：因产品缺失返回 ErrNotFound。
	if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.firstExp, clk.firstAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("reserve while product missing: got %v, want ErrNotFound", err)
	}

	// 失败不能产生承诺：编号未被占用，请求下也没有任何承诺明细。
	if _, err := s.Commitment(lpCommitID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("failed reserve created a commitment: got %v", err)
	}
	if view, err := s.RequestView(lpReqID, clk.firstAt); err == nil {
		t.Fatalf("request view should still report missing product, got view with %d commitments",
			len(view.Commitments))
	}

	// 实物仍为 10、有效占用仍为 4、可承诺仍为 6（另一张请求的占用不变）。
	assertStock10x6(t, s, clk.firstAt)

	// 该请求的预留历史留下产品缺失的失败记录。
	h, err := s.RequestHistory(lpReqID)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(h) != 1 {
		t.Fatalf("history len = %d, want 1", len(h))
	}
	assertMissingProductFailureRecord(t, h[0], 1, clk)

	// 另一张请求的 4 件占用与它自己的历史均保持原值。
	other, err := s.RequestHistory(lpOtherReqID)
	if err != nil {
		t.Fatalf("other history: %v", err)
	}
	if len(other) != 1 || !other[0].Success || other[0].CommitID != lpOtherCommit || other[0].Quantity != 4 {
		t.Fatalf("other request history altered: %+v", other)
	}
}

// TestRequestBeforeProduct_RegisterEligibleThenRetrySucceeds 补登合格条款：
// 购买时刻不晚于本次判断时刻、保修尚未到期且故障未被除外。无需再次提交
// 或替换请求，再查询原请求时资格按登记资料正常判断；沿用刚才失败的承诺
// 编号和预留内容、到期时刻仍晚于本次时刻时成功预留 3 件。实物仍 10 件、
// 有效占用变为 7、可承诺变为 3，另一张请求的 4 件保持原值。成功历史的
// 资格依据对应补登条款，库存依据是新增占用前的 10/4/6。此前的产品缺失
// 记录仍在前面且依据仍为空，不被回填或覆盖，两条记录序号各自递增。
func TestRequestBeforeProduct_RegisterEligibleThenRetrySucceeds(t *testing.T) {
	s, clk := lpBaseScenario(t)

	// 产品缺失期间先失败一次，留下 seq=1 的缺失记录。
	if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.firstExp, clk.firstAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("reserve while product missing: got %v, want ErrNotFound", err)
	}
	assertStock10x6(t, s, clk.firstAt)

	// 补登产品：购买时刻不晚于本次判断时刻、保修 30 天（在 secondAt 尚未到期）、
	// 除外清单不含 NOISE。
	if err := s.RegisterProduct(lpProductID, clk.purchase, 30, []string{"BROKEN_SEAL"}); err != nil {
		t.Fatalf("register product after request: %v", err)
	}

	// 无需再次提交或替换请求：原请求的资格按补登资料正常判断。
	e, err := s.Evaluate(lpReqID, clk.secondAt)
	if err != nil {
		t.Fatalf("evaluate after registration: %v", err)
	}
	if !e.Eligible || e.Excluded || len(e.Reasons) != 0 {
		t.Fatalf("expected eligible under late-registered terms, got %+v", e)
	}
	if e.ProductID != lpProductID || e.FaultCode != lpFaultCode {
		t.Fatalf("eligibility identity = %q/%q, want %q/%q", e.ProductID, e.FaultCode, lpProductID, lpFaultCode)
	}
	if !e.PurchaseTime.Equal(clk.purchase) || e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(clk.deadline) {
		t.Fatalf("eligibility basis = (%v, %d, %v), want late-registered terms (%v, 30, %v)",
			e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry, clk.purchase, clk.deadline)
	}
	// 按请求查看同样按补登条款判断，并仍无关联承诺。
	view, err := s.RequestView(lpReqID, clk.secondAt)
	if err != nil {
		t.Fatalf("request view after registration: %v", err)
	}
	if !view.Eligibility.Eligible || len(view.Commitments) != 0 {
		t.Fatalf("view after registration: eligible=%v commitments=%+v", view.Eligibility.Eligible, view.Commitments)
	}

	// 沿用刚才失败的承诺编号和预留内容再次申请，到期时刻仍晚于本次时刻：成功。
	c, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.secondExp, clk.secondAt)
	if err != nil {
		t.Fatalf("retry reserve after registration: %v", err)
	}
	if c.ID != lpCommitID || c.RequestID != lpReqID || c.PartID != lpPartID ||
		c.Quantity != 3 || c.Used != 0 || c.Canceled || c.Expired {
		t.Fatalf("bad commitment: %+v", c)
	}
	if !c.Expiry.Equal(clk.secondExp) {
		t.Fatalf("commitment expiry = %v, want %v", c.Expiry, clk.secondExp)
	}

	// 实物仍 10 件，有效占用变为 7（4+3），可承诺变为 3。
	st, err := s.PartStatus(lpPartID, clk.secondAt)
	if err != nil {
		t.Fatalf("part status: %v", err)
	}
	if st.PhysicalRemaining != 10 || st.ActiveOccupied != 7 || st.Committable != 3 {
		t.Fatalf("stock after success = phys %d / occupied %d / committable %d, want 10/7/3",
			st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
	}
	// 另一张请求的 4 件占用保持原值。
	other, err := s.Commitment(lpOtherCommit)
	if err != nil {
		t.Fatalf("other commitment: %v", err)
	}
	if other.Quantity != 4 || other.Used != 0 || other.Canceled || other.Expired {
		t.Fatalf("other commitment altered: %+v", other)
	}
	// 明细恰为两笔有效承诺，数量分别为 4 和 3。
	if len(st.Details) != 2 {
		t.Fatalf("part details = %+v, want 2 active commitments", st.Details)
	}
	byID := map[string]CommitmentDetail{}
	for _, d := range st.Details {
		byID[d.CommitmentID] = d
		if d.Status != CommitmentActive {
			t.Fatalf("commitment %q status = %q, want active", d.CommitmentID, d.Status)
		}
	}
	if byID[lpOtherCommit].OriginalQuantity != 4 || byID[lpCommitID].OriginalQuantity != 3 {
		t.Fatalf("detail quantities altered: other=%d retry=%d",
			byID[lpOtherCommit].OriginalQuantity, byID[lpCommitID].OriginalQuantity)
	}

	// 历史两条：此前的产品缺失记录仍在前面（seq=1），依据仍为空；
	// 成功记录在后（seq=2），不覆盖也不回填前一条。
	h, err := s.RequestHistory(lpReqID)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(h) != 2 {
		t.Fatalf("history len = %d, want 2", len(h))
	}
	assertMissingProductFailureRecord(t, h[0], 1, clk)
	ok := h[1]
	if ok.Seq != 2 || !ok.Success || ok.Error != "" {
		t.Fatalf("second record should be success with seq 2: %+v", ok)
	}
	if ok.CommitID != lpCommitID || ok.PartID != lpPartID || ok.Quantity != 3 ||
		!ok.Expiry.Equal(clk.secondExp) || !ok.Now.Equal(clk.secondAt) {
		t.Fatalf("success submission content: %+v", ok)
	}
	// 成功历史的资格依据对应补登的产品条款。
	if ok.Eligibility == nil {
		t.Fatal("success record missing eligibility basis")
	}
	if !ok.Eligibility.Eligible || ok.Eligibility.Excluded || len(ok.Eligibility.Reasons) != 0 ||
		ok.Eligibility.ProductID != lpProductID || ok.Eligibility.FaultCode != lpFaultCode ||
		!ok.Eligibility.PurchaseTime.Equal(clk.purchase) || ok.Eligibility.WarrantyDays != 30 ||
		!ok.Eligibility.WarrantyExpiry.Equal(clk.deadline) {
		t.Fatalf("success eligibility basis should match late-registered terms: %+v", ok.Eligibility)
	}
	// 库存依据是新增占用前的 10 件实物、4 件占用和 6 件可承诺。
	if ok.StockBasis == nil {
		t.Fatal("success record missing stock basis")
	}
	if ok.StockBasis.PhysicalRemaining != 10 || ok.StockBasis.ActiveOccupied != 4 ||
		ok.StockBasis.Committable != 6 {
		t.Fatalf("success stock basis = %+v, want pre-addition 10/4/6", ok.StockBasis)
	}

	// 补登与成功预留都不改变原请求的产品编号与故障代码。
	req, err := s.Request(lpReqID)
	if err != nil {
		t.Fatalf("request lookup: %v", err)
	}
	if req.ProductID != lpProductID || req.FaultCode != lpFaultCode {
		t.Fatalf("request identity altered: %+v", req)
	}
}

// TestRequestBeforeProduct_RegisterExcludingTermsRejects 另一种补登条件：
// 登记的条款已将原请求的故障代码列为除外。资格明确显示除外原因，预留
// 返回 ErrIneligible；不新增占用，失败历史保存本次已取得的资格与库存
// 依据；原请求的产品编号、故障代码及此前缺失资料的记录均保留。
func TestRequestBeforeProduct_RegisterExcludingTermsRejects(t *testing.T) {
	s, clk := lpBaseScenario(t)

	// 产品缺失期间先失败一次，留下 seq=1 的缺失记录。
	if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.firstExp, clk.firstAt); !errors.Is(err, ErrNotFound) {
		t.Fatalf("reserve while product missing: got %v, want ErrNotFound", err)
	}

	// 补登条款把原请求的故障代码 NOISE 列为除外（保修期本身仍有效）。
	if err := s.RegisterProduct(lpProductID, clk.purchase, 30, []string{lpFaultCode}); err != nil {
		t.Fatalf("register excluding product: %v", err)
	}

	// 资格明确显示除外原因：不合格、命中除外、拒绝原因恰为故障除外一项。
	e, err := s.Evaluate(lpReqID, clk.secondAt)
	if err != nil {
		t.Fatalf("evaluate after excluding registration: %v", err)
	}
	if e.Eligible || !e.Excluded {
		t.Fatalf("expected excluded, got %+v", e)
	}
	if len(e.Reasons) != 1 || e.Reasons[0] != ReasonFaultExcluded {
		t.Fatalf("reasons = %v, want exactly [fault_code_excluded]", e.Reasons)
	}
	if !e.PurchaseTime.Equal(clk.purchase) || e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(clk.deadline) {
		t.Fatalf("eligibility basis = (%v, %d, %v), want late-registered terms",
			e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry)
	}
	view, err := s.RequestView(lpReqID, clk.secondAt)
	if err != nil {
		t.Fatalf("request view: %v", err)
	}
	if view.Eligibility.Eligible || !view.Eligibility.Excluded ||
		len(view.Eligibility.Reasons) != 1 || view.Eligibility.Reasons[0] != ReasonFaultExcluded {
		t.Fatalf("view eligibility = %+v, want fault_code_excluded", view.Eligibility)
	}

	// 沿用同一编号与预留内容再次申请：返回 ErrIneligible。
	if _, err := s.Reserve(lpCommitID, lpReqID, lpPartID, 3, clk.secondExp, clk.secondAt); !errors.Is(err, ErrIneligible) {
		t.Fatalf("reserve under excluding terms: got %v, want ErrIneligible", err)
	}

	// 不新增占用：实物 10、有效占用 4、可承诺 6，且不生成承诺。
	assertStock10x6(t, s, clk.secondAt)
	if _, err := s.Commitment(lpCommitID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("ineligible retry created a commitment: got %v", err)
	}
	view, err = s.RequestView(lpReqID, clk.secondAt)
	if err != nil {
		t.Fatalf("request view after ineligible retry: %v", err)
	}
	if len(view.Commitments) != 0 {
		t.Fatalf("ineligible retry gained commitments: %+v", view.Commitments)
	}

	// 历史两条：此前缺失记录保留在前且依据为空；本次失败记录保存已取得的
	// 资格与库存依据（备件存在，库存依据非空）。
	h, err := s.RequestHistory(lpReqID)
	if err != nil {
		t.Fatalf("history: %v", err)
	}
	if len(h) != 2 {
		t.Fatalf("history len = %d, want 2", len(h))
	}
	assertMissingProductFailureRecord(t, h[0], 1, clk)
	excl := h[1]
	if excl.Seq != 2 || excl.Success || excl.Error != HistoryErrorIneligible {
		t.Fatalf("second record should be ineligible failure with seq 2: %+v", excl)
	}
	if excl.CommitID != lpCommitID || excl.PartID != lpPartID || excl.Quantity != 3 ||
		!excl.Expiry.Equal(clk.secondExp) || !excl.Now.Equal(clk.secondAt) {
		t.Fatalf("ineligible submission content: %+v", excl)
	}
	if excl.Eligibility == nil {
		t.Fatal("ineligible record should preserve the obtained eligibility")
	}
	if excl.Eligibility.Eligible || !excl.Eligibility.Excluded ||
		len(excl.Eligibility.Reasons) != 1 || excl.Eligibility.Reasons[0] != ReasonFaultExcluded ||
		excl.Eligibility.ProductID != lpProductID || excl.Eligibility.FaultCode != lpFaultCode ||
		!excl.Eligibility.PurchaseTime.Equal(clk.purchase) || excl.Eligibility.WarrantyDays != 30 ||
		!excl.Eligibility.WarrantyExpiry.Equal(clk.deadline) {
		t.Fatalf("ineligible record eligibility should match late-registered excluding terms: %+v", excl.Eligibility)
	}
	if excl.StockBasis == nil {
		t.Fatal("ineligible record should preserve the obtained stock basis")
	}
	if excl.StockBasis.PhysicalRemaining != 10 || excl.StockBasis.ActiveOccupied != 4 ||
		excl.StockBasis.Committable != 6 {
		t.Fatalf("ineligible record stock basis = %+v, want 10/4/6", excl.StockBasis)
	}

	// 原请求的产品编号与故障代码均保留。
	req, err := s.Request(lpReqID)
	if err != nil {
		t.Fatalf("request lookup: %v", err)
	}
	if req.ProductID != lpProductID || req.FaultCode != lpFaultCode {
		t.Fatalf("request identity altered: %+v", req)
	}
}

package warranty

import (
	"fmt"
	"time"
)

// stockAccountLocked 按统一的库存规则核算指定备件当前的账目：实物剩余只扣除
// 成功使用的数量（即备件当前库存），有效占用是该备件所有未取消、未确认到期
// 承诺的未用总量，可承诺数量等于实物剩余减去有效占用。已取消或已确认到期的
// 承诺不计入占用；到期一经确认不可逆，与本次传入的当前时刻无关，因此这里
// 不接收当前时刻，时刻相关的到期确认由调用方在核算前对本次涉及的承诺显式
// 完成。新预留的库存核算与按备件的库存查询共用这一份账目，同一条库存规则
// 不再分别维护。
//
// 调用方须已确认备件存在。
func (s *Store) stockAccountLocked(partID string) StockBasis {
	account := StockBasis{PhysicalRemaining: s.parts[partID].Stock}
	for _, c := range s.commitments {
		if c.PartID != partID {
			continue
		}
		if c.Canceled || c.Expired {
			continue
		}
		account.ActiveOccupied += c.Unused()
	}
	account.Committable = account.PhysicalRemaining - account.ActiveOccupied
	return account
}

// Reserve 为请求预留一种备件，数量为正整数，到期时刻必须晚于本次提交的当前时刻。
// 每次首次预留都按当次时刻重新判断资格；可承诺数量等于剩余实物库存扣除所有
// 有效承诺的未用数量。库存不足、未知请求或备件、不合格请求都不占用数量。
//
// 新预留的库存核算会先按本次当前时刻确认该备件下已到期的承诺：当前时刻达到
// 其到期时刻的未取消承诺被永久标记到期，只释放未用占用、不增加实物库存；该
// 结果不可逆，之后即使传入更早时刻核算也不再计算其未用数量，不能再次占用已
// 释放给其他请求的数量。空编号、非正数量等参数非法，或请求、备件（含资格所
// 需产品）不存在而提前失败的调用，不用本次时刻确认任何承诺。
//
// 提交编号全局唯一。已成功的编号：
//   - 原样重试（请求编号、备件编号、数量和到期时刻一致；当前时刻不属于提交内容，
//     到期时刻按实际时刻比较，换时区表示仍算一致）只取回首次预留成功的完整承诺，
//     其中已用数量仍为零、取消标记仍为否，不重新判断资格与库存，不重复占用，不
//     追加历史，也不恢复已释放占用或补回已扣减的实物库存；无论请求后来过保、库存
//     不足，还是承诺已分批使用、全部使用、取消或到期，即使本次当前时刻等于或晚于
//     原到期时刻，均如此。
//   - 改请求、备件、数量或到期时刻任一项即返回 ErrConflict，即使新参数本身非法
//     （空请求、未知备件、零数量、已过去的到期时刻）也按编号冲突处理；失败记录挂在
//     本次提交指定的已知请求下，请求为空或不存在时不创建请求和历史。
//
// 首次成功与编号绑定在同一临界区内原子完成：同一个尚未成功预留的编号被两组不同
// 内容（请求、备件、数量或到期时刻不同）并发抢占，且每组内容都可能同时提交多次
// 时，只能有一份内容成为首次承诺——与其完全相同的并发提交全部成功并返回同一份
// 完整首次承诺（已用数量为零、未取消），另一组全部返回 ErrConflict，不能两笔都
// 成功，也不会把后来的内容写进已经成功的承诺；即使库存充足到能同时容纳两笔数量，
// 有效占用也只对应获胜数量（预留不扣减实物库存），承诺只归获胜请求。库存恰好被
// 首次成功预留用完时，同内容的其余并发提交仍取回首次结果而不是 ErrInsufficientStock，
// 另一组仍报编号冲突；赛后按胜出内容重试取回首次承诺，按落败内容重试仍冲突，库存
// 与归属保持原结果。获胜请求只留一条首次成功记录（保存当次资格与新增占用前的库存
// 依据），相同内容的其余成功返回不追加；落败请求的每次提交各留一条冲突失败记录，
// 保留当次数量、到期时刻与当前时刻，资格与库存依据均为空，记录不挂到获胜请求下。
//
// 尚未成功占用的编号继续按本次参数、资格和库存判断；失败记录照常保留，失败后允许
// 用该编号再次提交。每次首次预留成功及每次失败提交都会在对应请求下留下记录。
func (s *Store) Reserve(commitID, requestID, partID string, quantity int, expiry, now time.Time) (Commitment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 本次提交的历史记录骨架：承诺编号、备件、数量、到期时刻与当前时刻在各分支
	// 一致，统一在这里填写，各分支不再重复。record 按统一规则留痕：成功标记与
	// 失败类别互斥，资格与库存依据快照原样保存（提前失败时为 nil，不用合格资格
	// 或零库存替代缺失）；请求为空或尚未登记时不创建请求和历史。
	base := HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
	}
	record := func(success bool, herr HistoryError, elig *Eligibility, basis *StockBasis) {
		rec := base
		rec.Success = success
		rec.Error = herr
		rec.Eligibility = cloneEligibility(elig)
		rec.StockBasis = basis
		s.recordReserveLocked(requestID, rec)
	}

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：原样重试不因本次当前
	// 时刻晚于到期时刻等参数问题失败；改内容则一律冲突。
	if first, ok := s.firstResults[commitID]; ok {
		if first.RequestID != requestID || first.PartID != partID ||
			first.Quantity != quantity || !first.Expiry.Equal(expiry) {
			// 冲突：在本次提交指定的已知请求下记录失败，不挂到原承诺所属请求。
			record(false, HistoryErrorConflict, nil, nil)
			return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
		}
		// 原样重试：返回首次成功时的承诺快照，不反映后来的使用、取消或到期。
		return first, nil
	}

	if commitID == "" || requestID == "" || partID == "" {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: commit/request/part id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: reserve quantity must be a positive integer", ErrInvalidParam)
	}
	if !expiry.After(now) {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: expiry must be after current time", ErrInvalidParam)
	}

	req, ok := s.requests[requestID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	if _, ok := s.parts[partID]; !ok {
		record(false, HistoryErrorPartNotFound, nil, nil)
		return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	elig, err := s.evaluateLocked(req, now)
	if err != nil {
		// 产品未登记：资格依据明确为空，不用合格替代缺失。
		record(false, HistoryErrorProductNotFound, nil, nil)
		return Commitment{}, err
	}

	// 库存核算前先按本次时刻确认该备件已到期的承诺。到期确认不可逆，之后
	// 即使传入更早时刻也不再计入占用。放在参数与引用校验之后：提前失败的
	// 非法或缺失引用调用不确认任何承诺。
	s.confirmPartExpiriesLocked(partID, now)

	// 库存依据：本次提交处理前的实物剩余、有效占用与可承诺数量，与库存
	// 查询共用同一份核算；在新增承诺落库之前取快照，本次新增占用不计入。
	stockBasis := s.stockAccountLocked(partID)

	if !elig.Eligible {
		record(false, HistoryErrorIneligible, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
	}

	if quantity > stockBasis.Committable {
		record(false, HistoryErrorInsufficientStock, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: need %d, committable %d", ErrInsufficientStock, quantity, stockBasis.Committable)
	}

	c := &Commitment{
		ID:        commitID,
		RequestID: requestID,
		PartID:    partID,
		Quantity:  quantity,
		Expiry:    expiry,
	}
	// 成功记录、承诺与首次结果快照在同一把锁内同时落库，查询不会看到只占用库存
	// 却没有成功记录的中间状态；快照独立于活动承诺，之后的使用、取消或到期不
	// 会改变原样重试取回的值。
	s.commitments[commitID] = c
	s.firstResults[commitID] = *c
	record(true, "", elig, &stockBasis)
	return *c, nil
}

// Use 使用一笔承诺，数量为正整数，分批扣减该承诺未用数量和剩余实物库存。
// 数量超过未用数量时整次失败，不改变任何记录。
//
// 使用编号全局唯一：相同编号且相同内容的重试返回首次成功结果，不再次扣减，
// 也不借本次时刻确认任何承诺到期；编号一旦已有成功记录，后续提交的承诺编号或
// 数量与首次成功内容不同即返回 ErrConflict——即使新内容本身非法（空承诺编号、
// 指向不存在的承诺、数量为零或负数、超过承诺余量），或新指定的承诺已取消或
// 到期，也一律按编号冲突处理：不扣减实物库存、不改变任何承诺的已用数量、不
// 释放占用，也不借本次时刻确认原承诺或新承诺到期，更不会用新内容覆盖原记录。
// 首次成功与编号绑定在同一临界区内原子完成：多个相同内容的并发提交全部成功并
// 返回同一份完整使用记录，但承诺累计已用数量与实物库存只随首次成功变化一次
// （恰好耗尽余量时其余提交仍取回首次结果，不会被当作新的超量使用）；首次成功
// 前两组不同内容并发抢占同一编号时，只有一份内容成为成功记录，与其相同的提交
// 全部取回该结果，另一组全部 ErrConflict，扣减量只对应胜出内容，落败承诺不变。
// 已经成功的使用在承诺取消或到期后原样重试，仍返回原结果，已确认到期的承诺
// 也不会因此重新开放。新使用（非重试）会按本次当前时刻确认这一笔承诺：已取消
// 或已确认到期，或本次时刻达到其到期时刻的，一律返回 ErrCommitmentClosed；到期
// 一经确认不可逆，之后即使传入更早时刻也仍被拒绝。尚无成功记录的编号按本次
// 参数处理：空编号、空承诺编号、非正数量返回 ErrInvalidParam，引用未知承诺返回
// ErrNotFound，这些提前失败不用本次时刻确认到期，也不占用编号，修正内容后仍可
// 提交。已全部使用的承诺不再接受新使用。
func (s *Store) Use(usageID, commitID string, quantity int, now time.Time) (Usage, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：沿用成功编号但把
	// 承诺编号改成空串或未知承诺、把数量改成零或负数等本身非法的内容，仍属于
	// 对已成功提交内容的改动，按 ErrConflict 处理，与普通非法输入区分。成功
	// 使用的编号必非空，因此空编号不会命中这里，继续走参数校验。
	if existing, ok := s.usages[usageID]; ok {
		if existing.CommitmentID != commitID || existing.Quantity != quantity {
			return Usage{}, fmt.Errorf("%w: usage id %q reused with different content", ErrConflict, usageID)
		}
		return *existing, nil
	}

	if usageID == "" || commitID == "" {
		return Usage{}, fmt.Errorf("%w: usage/commit id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		return Usage{}, fmt.Errorf("%w: usage quantity must be a positive integer", ErrInvalidParam)
	}

	c, ok := s.commitments[commitID]
	if !ok {
		return Usage{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	// 新使用判断：按本次时刻确认这一笔承诺是否到期。一经确认不可逆，之后
	// 即使传入更早时刻也一律关闭。已取消的承诺不确认到期，仍保持 canceled。
	s.confirmExpiryLocked(c, now)
	if c.Canceled {
		return Usage{}, fmt.Errorf("%w: commitment %q is canceled", ErrCommitmentClosed, commitID)
	}
	if c.Expired {
		return Usage{}, fmt.Errorf("%w: commitment %q expired at %v", ErrCommitmentClosed, commitID, c.Expiry)
	}
	if quantity > c.Quantity-c.Used {
		return Usage{}, fmt.Errorf("%w: need %d, unused %d", ErrUsageExceeded, quantity, c.Quantity-c.Used)
	}

	c.Used += quantity
	s.parts[c.PartID].Stock -= quantity
	u := &Usage{ID: usageID, CommitmentID: commitID, Quantity: quantity}
	s.usages[usageID] = u
	return *u, nil
}

// Cancel 取消承诺，只释放未用数量，不影响已扣减的实物库存。
// 重复取消不增加库存；承诺已到期时余量已自动失效，取消同样不产生变化。
// 取消后的承诺不能继续使用。
func (s *Store) Cancel(commitID string, now time.Time) (Commitment, error) {
	if commitID == "" {
		return Commitment{}, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	c, ok := s.commitments[commitID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	if !c.Canceled {
		c.Canceled = true
	}
	return *c, nil
}

package warranty

import (
	"fmt"
	"sort"
	"time"
)

// CommitmentDetail 是承诺的明细视图，已取消或已到期的记录仍可追查。
type CommitmentDetail struct {
	// CommitmentID 是承诺编号。
	CommitmentID string
	// RequestID 是关联请求编号。
	RequestID string
	// PartID 是备件编号。
	PartID string
	// OriginalQuantity 是原定承诺数量。
	OriginalQuantity int
	// UsedQuantity 是已用数量。
	UsedQuantity int
	// RemainingQuantity 是剩余未用数量。
	RemainingQuantity int
	// Expiry 是到期时刻。
	Expiry time.Time
	// Status 是在查询时刻的状态（active/canceled/expired）。
	Status CommitmentStatus
}

// PartStatus 是按备件查询的库存与占用视图。
type PartStatus struct {
	// PartID 是备件编号。
	PartID string
	// PhysicalRemaining 是剩余实物库存（初始库存扣除全部成功使用量）。
	PhysicalRemaining int
	// ActiveOccupied 是有效承诺的未用总量。
	ActiveOccupied int
	// Committable 是还可承诺数量，等于剩余实物库存扣除有效承诺未用总量。
	Committable int
	// Details 是该备件的全部承诺明细（含已取消、已到期），按承诺编号排序。
	Details []CommitmentDetail
}

// RequestView 是按请求查询的资格与承诺视图。
type RequestView struct {
	// Eligibility 是资格依据与拒绝原因。
	Eligibility *Eligibility
	// Commitments 是该请求关联的全部承诺明细（含已取消、已到期），按承诺编号排序。
	Commitments []CommitmentDetail
}

// toDetailLocked 生成承诺在指定时刻的明细。
func toDetailLocked(c *Commitment, now time.Time) CommitmentDetail {
	return CommitmentDetail{
		CommitmentID:      c.ID,
		RequestID:         c.RequestID,
		PartID:            c.PartID,
		OriginalQuantity:  c.Quantity,
		UsedQuantity:      c.Used,
		RemainingQuantity: c.Quantity - c.Used,
		Expiry:            c.Expiry,
		Status:            c.Status(now),
	}
}

// commitmentDetailsLocked 是两种查询入口共用的承诺明细处理规则：收集全部满足
// match 的承诺（含已取消、已到期、已全部使用的记录），按本次时刻生成明细，
// 并按承诺编号升序排序。按请求查询与按备件查询只传入不同的归属条件，过滤、
// 明细生成与排序规则不再分别维护。返回的明细是独立副本，与仓库记录互不影响。
func (s *Store) commitmentDetailsLocked(match func(*Commitment) bool, now time.Time) []CommitmentDetail {
	var details []CommitmentDetail
	for _, c := range s.commitments {
		if !match(c) {
			continue
		}
		details = append(details, toDetailLocked(c, now))
	}
	sort.Slice(details, func(i, j int) bool {
		return details[i].CommitmentID < details[j].CommitmentID
	})
	return details
}

// RequestView 返回指定请求在当前时刻的资格依据、拒绝原因和关联承诺。
// 查询会按本次当前时刻确认该请求下已到期的承诺：到期一经确认不可逆，之后
// 即使传入更早时刻，这些承诺也始终显示 expired、不再计入有效占用；到期时刻
// 前尚未确认失效的承诺仍按本次时刻显示 active。资格仍只按本次时刻判断，
// 不会用较大的历史时刻替换本次时刻。
func (s *Store) RequestView(requestID string, now time.Time) (*RequestView, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	req, ok := s.requests[requestID]
	if !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	// 查询本身确认到期：本次时刻已达到到期时刻的关联承诺一经确认不可逆，
	// 之后即使传入更早时刻也不再计入占用、状态保持 expired。
	s.confirmRequestExpiriesLocked(requestID, now)
	elig, err := s.evaluateLocked(req, now)
	if err != nil {
		return nil, err
	}
	view := &RequestView{Eligibility: elig}
	view.Commitments = s.commitmentDetailsLocked(func(c *Commitment) bool {
		return c.RequestID == requestID
	}, now)
	return view, nil
}

// PartStatus 返回指定备件在当前时刻的实物剩余、有效占用、可承诺数量和占用明细。
// 查询会按本次当前时刻确认该备件下已到期的承诺：到期一经确认不可逆，只释放
// 未用占用、不增加实物库存，之后即使传入更早时刻，这些承诺也不再计入有效占用
// （可承诺数量不回落），明细持续显示 expired；已取消的记录仍显示 canceled。
func (s *Store) PartStatus(partID string, now time.Time) (*PartStatus, error) {
	if partID == "" {
		return nil, fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.parts[partID]; !ok {
		return nil, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	// 查询本身确认到期：本次时刻已达到到期时刻的该备件承诺一经确认不可
	// 逆，之后即使传入更早时刻也不再计入占用。
	s.confirmPartExpiriesLocked(partID, now)
	// 实物剩余、有效占用与可承诺数量与新预留的库存核算共用同一条规则：
	// 占用只看持久状态，取消或已确认到期的承诺不占数量，不随本次时刻回退。
	account := s.stockAccountLocked(partID)
	view := &PartStatus{
		PartID:            partID,
		PhysicalRemaining: account.PhysicalRemaining,
		ActiveOccupied:    account.ActiveOccupied,
		Committable:       account.Committable,
	}
	view.Details = s.commitmentDetailsLocked(func(c *Commitment) bool {
		return c.PartID == partID
	}, now)
	return view, nil
}

package warranty

import (
	"fmt"
	"math"
	"time"
)

// unixEpochToInternal 是 Unix 秒与 time.Time 内部绝对秒之间的固定偏移
// （公元 1 年 1 月 1 日到 1970 年 1 月 1 日的秒数）。
const unixEpochToInternal = 62135596800

// secondsPerDay 是每天的秒数；保修期每天固定二十四小时，与时区无关。
const secondsPerDay = 24 * 60 * 60

// warrantyExpiry 计算保修截止时刻：自购买时刻起完整 days 个二十四小时。
// 不经过 time.Duration（其上限约 106751 天），较长保修期限不会溢出回绕；
// 秒以下精度与购买时刻的时区表示原样保留。days 为正整数但截止时刻超出
// 时间类型的可表示范围时返回 ok=false。
func warrantyExpiry(purchase time.Time, days int) (expiry time.Time, ok bool) {
	d := int64(days)
	if d <= 0 || d > math.MaxInt64/secondsPerDay {
		return time.Time{}, false
	}
	add := d * secondsPerDay
	unix := purchase.Unix()
	// 可表示的最大 Unix 秒为 math.MaxInt64 - unixEpochToInternal；
	// 写成 unix > max-add 避免任何中间量溢出。
	if unix > math.MaxInt64-unixEpochToInternal-add {
		return time.Time{}, false
	}
	return time.Unix(unix+add, int64(purchase.Nanosecond())).In(purchase.Location()), true
}

// RejectionReason 是资格拒绝原因。
type RejectionReason string

const (
	// ReasonPurchaseInFuture 表示购买时刻晚于当前时刻。
	ReasonPurchaseInFuture RejectionReason = "purchase_time_in_future"
	// ReasonWarrantyExpired 表示当前时刻已达到或超过保修截止时刻。
	ReasonWarrantyExpired RejectionReason = "warranty_expired"
	// ReasonFaultExcluded 表示故障代码在除外清单中。
	ReasonFaultExcluded RejectionReason = "fault_code_excluded"
)

// Eligibility 是按请求查询的资格依据与拒绝原因。
type Eligibility struct {
	// RequestID 是请求编号。
	RequestID string
	// ProductID 是产品编号。
	ProductID string
	// FaultCode 是故障代码。
	FaultCode string
	// Eligible 表示在当次时刻是否合格。
	Eligible bool
	// Reasons 列出全部拒绝原因；过保与除外同时成立时会列出两项。
	Reasons []RejectionReason
	// PurchaseTime 是购买时刻（资格依据）。
	PurchaseTime time.Time
	// WarrantyDays 是保修天数（资格依据）。
	WarrantyDays int
	// WarrantyExpiry 是保修截止时刻，自购买时刻起按每天二十四小时计算；
	// 当前时刻达到该时刻即算过保。
	WarrantyExpiry time.Time
	// Excluded 表示故障代码是否命中除外清单。
	Excluded bool
}

// evaluateLocked 在已持锁的情况下计算请求在当前时刻的资格。
// 未知产品返回 ErrNotFound，缺少故障代码返回 ErrInvalidParam。
func (s *Store) evaluateLocked(req *Request, now time.Time) (*Eligibility, error) {
	prod, ok := s.products[req.ProductID]
	if !ok {
		return nil, fmt.Errorf("%w: product %q", ErrNotFound, req.ProductID)
	}
	if req.FaultCode == "" {
		return nil, fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
	}
	// 登记时已校验截止时刻可表示，这里一定成功。
	expiry, _ := warrantyExpiry(prod.PurchaseTime, prod.WarrantyDays)
	e := &Eligibility{
		RequestID:      req.ID,
		ProductID:      prod.ID,
		FaultCode:      req.FaultCode,
		PurchaseTime:   prod.PurchaseTime,
		WarrantyDays:   prod.WarrantyDays,
		WarrantyExpiry: expiry,
	}
	if prod.PurchaseTime.After(now) {
		e.Reasons = append(e.Reasons, ReasonPurchaseInFuture)
	}
	if !now.Before(e.WarrantyExpiry) {
		e.Reasons = append(e.Reasons, ReasonWarrantyExpired)
	}
	if _, excluded := prod.ExcludedCodes[req.FaultCode]; excluded {
		e.Excluded = true
		e.Reasons = append(e.Reasons, ReasonFaultExcluded)
	}
	e.Eligible = len(e.Reasons) == 0
	return e, nil
}

// Evaluate 返回指定请求在当前时刻的资格依据与拒绝原因。
// 未知产品或缺少故障代码时明确失败，不产生任何承诺。
func (s *Store) Evaluate(requestID string, now time.Time) (*Eligibility, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	req, ok := s.requests[requestID]
	if !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	return s.evaluateLocked(req, now)
}

